SELECT EXISTS(
    SELECT 1 FROM referral_sources
    WHERE id = #{id}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1 FROM referral_sources
    WHERE name = #{name}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1 FROM referral_sources
    WHERE name = #{name}
      AND id <> #{id}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1 FROM students WHERE referral_source_id = #{id}
)
